// Raw voltage diagnostics, before code multiplication, whitening or HPF.
use anyhow::{Result,ensure};use rustplotlib::*;use rustfft::{FftPlanner,num_complex::Complex64};use std::path::PathBuf;
fn edges(v:&[f64])->Vec<f64>{let d=v[1]-v[0];(0..=v.len()).map(|i|v[0]+(i as f64-0.5)*d).collect()}
fn label(s:impl Into<String>,x:f64,y:f64)->Label{let mut l=Label::new(s,x,y);l.color="#ffffff".into();l.background=Some("#000000".into());l.padding_mm=0.35;l}
fn utc_text(stamp:f64)->String{chrono::DateTime::from_timestamp_micros((stamp*1e6).round()as i64).unwrap().format("%Y-%m-%d %H:%M:%S%.6f").to_string()}
fn main()->Result<()>{let a:Vec<String>=std::env::args().collect();let input=PathBuf::from(&a[1]);let out=PathBuf::from(&a[2]);std::fs::create_dir_all(&out)?;let nf=256;let hop=32;let win:Vec<f64>=(0..nf).map(|i|0.5-0.5*(std::f64::consts::TAU*i as f64/(nf-1)as f64).cos()).collect();let norm: f64=win.iter().map(|v|v*v).sum();let mut planner=FftPlanner::new();let fft=planner.plan_fft_forward(nf);
let mut paths:Vec<_>=std::fs::read_dir(&input)?.filter_map(|p|p.ok().map(|p|p.path())).filter(|p|p.extension().is_some_and(|s|s=="h5")).collect();paths.sort_by_key(|p|{let name=p.file_stem().unwrap().to_string_lossy();if name.contains("strong"){0}else if name.contains("before"){1}else if name.contains("after"){2}else if name.contains("early"){3}else{4}});
for path in paths{let f=hdf5::File::open(&path)?;if !f.link_exists("selected_record_indices"){continue;}let case=path.file_stem().unwrap().to_string_lossy();for j in 0..2{let group=format!("ipp{j}");if !f.link_exists(&group){continue;}let g=f.group(&group)?;let qi=g.dataset("qi_int32")?.read_raw::<i32>()?;let ne=qi.len()/2;let fs=g.attr("sample_rate_hz")?.read_scalar::<f64>()?;ensure!(fs==16e6,"unsupported sampling");let front=g.attr("front_us")?.read_scalar::<f64>()?;let center=g.attr("receiver_center_hz")?.read_scalar::<f64>()?;let stamp=g.attr("pulse_time_utc_s")?.read_scalar::<f64>()?;let reference=g.dataset("reference_passband_adu2")?.read_raw::<f64>()?;ensure!(reference.len()==1024,"reference frequency grid");let noise=reference.iter().sum::<f64>()/reference.len()as f64;
let nt=(ne-nf)/hop+1;let times:Vec<f64>=(0..nt).map(|i|(front+(i*hop)as f64/fs*1e6+(nf-1)as f64/(2.*fs)*1e6)/1000.).collect();let freq:Vec<f64>=(0..nf).map(|k|(center-430e6-fs/2.+k as f64*fs/nf as f64)/1e6).collect();let mut values=vec![0.;nt*nf];let mut buffer=vec![Complex64::default();nf];for i in 0..nt{for k in 0..nf{let ix=i*hop+k;buffer[k]=Complex64::new(qi[2*ix+1]as f64,qi[2*ix]as f64)*win[k];}fft.process(&mut buffer);for k in 0..nf{let power=buffer[(k+nf/2)%nf].norm_sqr()/norm;values[k*nt+i]=10.*(power/reference[k*4]).max(1e-30).log10();}}
let mut envelope=Vec::new();let mut peak=f64::NEG_INFINITY;let mut runs=Vec::new();let mut run=None;for i in 0..ne/32{let power=(0..32).map(|k|{let ix=i*32+k;let q=qi[ix*2]as f64;let v=qi[ix*2+1]as f64;q*q+v*v}).sum::<f64>()/32.;let db=10.*(power/noise).max(1e-30).log10();peak=peak.max(db);envelope.push([(front+(i*32)as f64/fs*1e6+15.5/fs*1e6)/1000.,db]);if db>9.{if run.is_none(){run=Some(i);}}else if let Some(start)=run.take(){runs.push((start,i));}}if let Some(start)=run{runs.push((start,envelope.len()));}let longest=runs.iter().map(|(s,e)|(e-s)as f64*2.).fold(0.,f64::max);let duty=runs.iter().map(|(s,e)|e-s).sum::<usize>()as f64/envelope.len()as f64;
let tag=format!("{case}-rx{:0.0}",center/1e6);let data=hdf5::File::create(out.join(format!("{tag}-spectrogram.h5")))?;data.new_dataset::<f32>().shape((nf,nt)).chunk((16,512)).deflate(1).create("relative_quiet_passband_db")?.write_raw(&values.iter().map(|&v|v as f32).collect::<Vec<_>>())?;for(name,v)in[("receive_delay_ms",times.as_slice()),("frequency_relative_to_430_mhz",freq.as_slice())]{data.new_dataset::<f64>().shape(v.len()).create(name)?.write_raw(v)?;}for(name,v)in[("header_time_utc_s",stamp),("receiver_center_hz",center),("stft_window_us",16.),("stft_step_us",2.),("peak_2us_power_above_reference_db",peak),("fraction_above_9db",duty),("longest_above_9db_us",longest)]{data.new_attr::<f64>().create(name)?.write_scalar(&v)?;}
let xmin=front/1000.;let xmax=(front+ne as f64/fs*1e6)/1000.;let ymin=(center-430e6)/1e6-8.;let ymax=ymin+16.;let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=200.;fig.height_mm=135.;fig.font_pt=7.;fig.tight_export=false;fig.check_label_bounds=false;fig.check_label_overlap=false;fig.check_label_geometry=false;fig.auto_colorbar_layout=false;let mut ax=Axes::new([xmin,xmax],[-5.,45.],"","");ax.show_x_axis=false;ax.show_y_axis=false;let mut panel=Panel::new(Rect::new(0.,13.,200.,28.),ax);let mut line=Line::new(envelope,"#111111");line.width_pt=0.4;panel.push(Layer::Line(line));fig.panels.push(panel);for v in [0.,10.,20.,30.,40.]{fig.labels.push(label(format!("{v:0.0}"),4.,13.+(45.-v)/50.*28.));}fig.labels.push(label("2 us band power / quiet reference (dB)",145.,15.));
let scale=fig.scale(Scale::new([-5.,35.],Normalization::Linear,ColorMap::inferno())?);let mut ax=Axes::new([xmin,xmax],[ymin,ymax],"","");ax.show_x_axis=false;ax.show_y_axis=false;let mut panel=Panel::new(Rect::new(0.,47.,200.,76.),ax);let mut field=Field::new(edges(&times),edges(&freq),values,scale)?;field.interpolate=false;panel.push(Layer::Pcolormesh(field));fig.panels.push(panel);for k in 0..=4{let v=ymin+k as f64*4.;fig.labels.push(label(format!("{v:0.0}"),4.,(47.+(ymax-v)/16.*76.).clamp(49.,121.)));}for v in [1.,2.,3.,4.,5.,6.,7.,8.,9.]{fig.labels.push(label(format!("{v:0.0}"),(v-xmin)/(xmax-xmin)*200.,121.));}fig.labels.push(label("Receive delay (ms)",100.,130.));let mut l=label("RF offset from 430 MHz (MHz)",8.,85.);l.rotation=-90.;fig.labels.push(l);
let timestamp=utc_text(stamp);fig.labels.push(label(format!("{} UTC; RX {:0.0} MHz",timestamp,center/1e6),100.,3.5));fig.labels.push(label("Raw voltage STFT: 16 us window, 2 us steps; before decoding / HPF",100.,8.));let mut bax=Axes::new([0.,1.],[-5.,35.],"","");bax.show_x_axis=false;bax.show_y_axis=false;let mut bar=Panel::new(Rect::new(195.,51.,1.3,30.),bax);let by:Vec<f64>=(0..=256).map(|i|-5.+40.*i as f64/256.).collect();let bv:Vec<f64>=(0..256).map(|i|-5.+40.*(i as f64+0.5)/256.).collect();bar.push(Layer::Pcolormesh(Field::new(vec![0.,1.],by,bv,scale)?));fig.panels.push(bar);fig.labels.push(label("Power / quiet passband (dB)",164.,49.));for v in [0.,10.,20.,30.]{fig.labels.push(label(format!("{v:0.0}"),191.,51.+(35.-v)/40.*30.));}
fig.raster_dpi=nt as f64*25.4/200.;let full=out.join(format!("{tag}-full.png"));fig.save(&full)?;let img=image::open(&full)?;let height=(img.height()as f64*1800./img.width()as f64).round()as u32;img.resize_exact(1800,height,image::imageops::FilterType::Lanczos3).save(out.join(format!("{tag}-preview.png")))?;println!("RFI {tag}: peak {peak:0.2} dB; fraction above9dB {duty:0.5}; longest {longest:0.1} us",);
}}
Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn header_utc_format(){assert_eq!(utc_text(1795587582.897425),"2026-11-25 06:19:42.897425");}}
